/**
 * Anfuehrer-Portraets: handgebaute Comic-Illustrationen (SVG in public/leaders, erzeugt von scripts/leader-art),
 * je Fraktion vier Stimmungen in zwei Detailstufen; dazu eine Fraktionskarte mit Name, Titel, Leitspruch und Hintergrund.
 * Leader portraits: hand-built comic illustrations (SVG in public/leaders, generated by scripts/leader-art),
 * four moods per faction in two detail levels; plus a faction card with name, title, motto and background.
 */
import type { FactionId } from '../data/balance';
import { t } from '../i18n/i18n';
import { esc } from './components';

/** Gesichtsausdruck / facial expression */
export type LeaderMood = 'neutral' | 'angry' | 'smug' | 'shocked';
/** Detailstufe: A = klarer Comic fuer kleine Groessen, B = reicher Comic fuer grosse Ansichten / A = clean comic for small sizes, B = rich comic for large views */
export type LeaderLevel = 'A' | 'B';

const BASE = `${import.meta.env.BASE_URL ?? '/'}leaders/`;
/** Groessenklassen, die die reiche Stufe B bekommen / size classes that get the rich level B */
const LARGE = ['lg', 'dispatch-face'];

/** Adresse des Portraets / URL of the portrait */
export function leaderImage(f: FactionId, mood: LeaderMood = 'neutral', level: LeaderLevel = 'B'): string {
  return `${BASE}${f}_${mood}_${level}.svg`;
}

/** Portraet-HTML; die Groessenklasse waehlt die Detailstufe / portrait HTML; the size class picks the detail level */
export function leaderPortrait(f: FactionId, cls = '', mood: LeaderMood = 'neutral'): string {
  const level: LeaderLevel = cls.split(/\s+/).some((c) => LARGE.includes(c)) ? 'B' : 'A';
  const name = t(`factions.${f}.leader`);
  return `<img class="leader-portrait ${cls}" src="${leaderImage(f, mood, level)}" alt="${esc(name)}" width="512" height="512" decoding="async" style="--leader-rim:var(--faction-${f}-primary)">`;
}

/** Fraktionskarte mit Anfuehrer und Hintergrund / faction card with leader and background */
export function factionCard(f: FactionId, opts: { compact?: boolean } = {}): string {
  const k = (s: string) => esc(t(`factions.${f}.${s}`));
  return `<div class="leader-card ${opts.compact ? 'compact' : ''}">
    ${leaderPortrait(f, opts.compact ? 'sm' : 'lg')}
    <div class="col grow">
      <strong class="display">${k('name')}</strong>
      <span><span class="muted">${esc(t('leaders.leader'))}:</span> ${k('leaderTitle')} <strong>${k('leader')}</strong></span>
      <q class="leader-quote">${k('quote')}</q>
      ${opts.compact ? '' : `<p>${k('lore')}</p>
      <p><span class="muted">${esc(t('leaders.perk'))}:</span> <strong>${k('perk')}</strong>, ${k('perkDesc')}</p>
      <p><span class="muted">${esc(t('leaders.perk2'))}:</span> <strong>${k('perk2')}</strong>, ${k('perk2Desc')}</p>
      <p class="muted">${esc(t('leaders.style'))}: ${k('style')}</p>
      <p class="muted">${esc(t('identity.aiStyle'))}: ${k('aiStyle')}</p>`}
    </div>
  </div>`;
}
